import { execFileSync } from 'node:child_process';
import { randomUUID } from 'node:crypto';
import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { dirname, relative, resolve, sep } from 'node:path';
import { verifySourceSnapshot } from '../../src/snapshot.js';

// Only maintainer-generated bytes enter this fixture. It is not a Runner or a repository import API.
export async function trustedGitFixture(format: 'sha1' | 'sha256' = 'sha1', content: Record<string, Uint8Array> = {
  'src/example.ts': Buffer.from('export const value = 1;\n'), 'src.first': Buffer.from('tree ordering\n'),
  'run.sh': Buffer.from('#!/bin/sh\nexit 0\n'), 'binary.dat': Buffer.from([0, 255, 10]),
}) {
  const parent = resolve('.reports/p1-d'); const nonce = randomUUID(); const root = resolve(parent, `git-${nonce}`);
  await mkdir(root, { recursive: true, mode: 0o700 });
  const env: NodeJS.ProcessEnv = { PATH: process.env.PATH, ...(process.env.SystemRoot ? { SystemRoot: process.env.SystemRoot } : {}),
    GIT_CONFIG_NOSYSTEM: '1', GIT_CONFIG_GLOBAL: process.platform === 'win32' ? 'NUL' : '/dev/null',
    GIT_AUTHOR_NAME: 'Trusted fixture', GIT_AUTHOR_EMAIL: 'fixture@example.invalid', GIT_COMMITTER_NAME: 'Trusted fixture', GIT_COMMITTER_EMAIL: 'fixture@example.invalid',
    GIT_AUTHOR_DATE: '2026-01-01T00:00:00Z', GIT_COMMITTER_DATE: '2026-01-01T00:00:00Z' };
  const git = (args: string[], input?: Uint8Array) => execFileSync('git', ['-C', root, '-c', 'core.autocrlf=false', '-c', 'core.hooksPath=/dev/null', ...args],
    { env, ...(input ? { input } : {}), timeout: 10_000, maxBuffer: 4 * 1024 * 1024, stdio: ['pipe', 'pipe', 'pipe'] });
  const close = async () => {
    const suffix = relative(parent, root);
    if (suffix !== `git-${nonce}` || suffix.includes(sep) || root === parent) throw new Error('Unsafe fixture cleanup');
    await rm(root, { recursive: true, force: true });
  };
  try {
    git(['init', '--template=', `--object-format=${format}`]);
    const files = [];
    for (const [path, bytes] of Object.entries(content)) {
      const location = resolve(root, path); if (!location.startsWith(root + sep)) throw new Error('Invalid trusted fixture path');
      await mkdir(dirname(location), { recursive: true }); await writeFile(location, bytes);
      files.push({ path, mode: path.endsWith('.sh') ? '100755' : '100644', content: bytes });
    }
    git(['add', '--all']);
    for (const file of files) if (file.mode === '100755') git(['update-index', '--chmod=+x', '--', file.path]);
    const tree = git(['write-tree']).toString().trim();
    const commit = git(['commit-tree', tree], Buffer.from('Trusted generated input\n')).toString().trim();
    const commitObject = git(['cat-file', 'commit', commit]); const source = { repositoryId: randomUUID(), commit };
    const manifest = verifySourceSnapshot({ source, commitObject, files });
    return { root, source, tree, commitObject, files, manifest, close, read: (path: string) => readFile(resolve(root, path)) };
  } catch (error) { await close(); throw error; }
}
